// Shape the error payload into fields we need for Linear + Pushover.
const err = $input.item.json || {};
const execution = err.execution || {};
const trigger = err.trigger || {};
const lastNode = (execution.lastNodeExecuted) || (err.node && err.node.name) || 'unknown';
const workflowName = (err.workflow && err.workflow.name) || 'unknown workflow';
const executionId = execution.id || '';
const executionUrl = execution.url || '';
const mode = execution.mode || '';
const ts = new Date().toISOString();

// Error message extraction — n8n puts the human-readable error in execution.error.message sometimes,
// other times under err.error. Walk both.
let errorMessage = '';
let errorStack = '';
if (execution.error) {
  errorMessage = execution.error.message || '';
  errorStack = execution.error.stack || '';
} else if (err.error) {
  errorMessage = err.error.message || '';
  errorStack = err.error.stack || '';
}

const fullPayload = JSON.stringify(err, null, 2);
const truncated = fullPayload.length > 8000 ? fullPayload.slice(0, 8000) + '\n\n... (truncated)' : fullPayload;

const title = `n8n ${workflowName} error — ${ts}`;
const description = [
  `**Workflow:** ${workflowName}`,
  `**Failed node:** ${lastNode}`,
  `**Execution ID:** ${executionId}`,
  `**Execution URL:** ${executionUrl}`,
  `**Mode:** ${mode}`,
  `**Timestamp:** ${ts}`,
  '',
  `**Error message:**`,
  '```',
  errorMessage || '(no message)',
  '```',
  '',
  `**Stack:**`,
  '```',
  errorStack || '(no stack)',
  '```',
  '',
  `**Full payload:**`,
  '```json',
  truncated,
  '```'
].join('\n');

return {
  json: {
    error_title: title,
    error_description: description,
    failed_workflow_name: workflowName,
    failed_node_name: lastNode,
    execution_id: executionId,
    execution_url: executionUrl
  }
};

