// Resolve Todo state ID and n8n-error-queue label ID.
const data = ($input.item.json && $input.item.json.data) || {};
const team = data.team || { states: { nodes: [] } };
const allLabels = (data.issueLabels && data.issueLabels.nodes) || [];

const todoState = (team.states.nodes || []).find(s => s.type === 'unstarted') || null;
const labelIdByName = {};
for (const l of allLabels) labelIdByName[l.name] = l.id;

const labelIds = [];
if (labelIdByName['n8n-error-queue']) labelIds.push(labelIdByName['n8n-error-queue']);

const shaped = $('Shape error payload').item.json;

return {
  json: {
    todo_state_id: todoState ? todoState.id : null,
    label_ids: labelIds,
    error_title: shaped.error_title,
    error_description: shaped.error_description,
    failed_workflow_name: shaped.failed_workflow_name,
    failed_node_name: shaped.failed_node_name,
    execution_id: shaped.execution_id,
    execution_url: shaped.execution_url
  }
};

